package com.primehr.rewardsrecognition.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="rr_nomination_evidence")
public class RrNominationEvidence extends RspAuditedEntity{public enum Visibility{NOMINEE_VISIBLE,COMMITTEE_RESTRICTED,PUBLICATION_SAFE}@Column(name="nomination_id",nullable=false,length=36)private String nominationId;@Column(nullable=false,length=200)private String title;@Column(name="original_filename",nullable=false,length=255)private String originalFilename;@Column(name="storage_provider",nullable=false,length=30)private String storageProvider;@Column(name="storage_object_key",nullable=false,length=500)private String storageObjectKey;@Column(name="media_type",nullable=false,length=120)private String mediaType;@Column(name="byte_size",nullable=false)private long byteSize;@Column(nullable=false,length=64)private String checksum;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private Visibility visibility;@Column(name="uploaded_by",nullable=false,length=100)private String uploadedBy;@Column(name="uploaded_at",nullable=false)private Instant uploadedAt;protected RrNominationEvidence(){}public RrNominationEvidence(String a,String n,String title,String filename,String provider,String key,String media,long size,String checksum,Visibility visibility,String actor,Instant at){super(a);nominationId=requiredText(n,"nominationId");this.title=requiredText(title,"title");originalFilename=requiredText(filename,"filename");storageProvider=requiredText(provider,"storageProvider");storageObjectKey=requiredText(key,"storageObjectKey");mediaType=requiredText(media,"mediaType");if(size<1)throw new IllegalArgumentException("byteSize must be positive");byteSize=size;this.checksum=requiredText(checksum,"checksum");this.visibility=java.util.Objects.requireNonNull(visibility);uploadedBy=requiredText(actor,"actor");uploadedAt=java.util.Objects.requireNonNull(at);}public String getNominationId(){return nominationId;}public String getTitle(){return title;}public String getOriginalFilename(){return originalFilename;}public String getStorageProvider(){return storageProvider;}public String getStorageObjectKey(){return storageObjectKey;}public String getMediaType(){return mediaType;}public long getByteSize(){return byteSize;}public String getChecksum(){return checksum;}public Visibility getVisibility(){return visibility;}public String getUploadedBy(){return uploadedBy;}public Instant getUploadedAt(){return uploadedAt;}}
